# Hypothesis: checkers reject writes to ReadOnly keys, extra keys in a closed TypedDict, and Unpack[TypedDict] calls that omit a Required key, while the runtime accepts all of these values and only fails on the missing kwarg lookup.
from typing_extensions import NotRequired, ReadOnly, Required, TypedDict, Unpack, reveal_type


class Point(TypedDict):
    x: int
    y: int
    label: NotRequired[str]


class Frozen(TypedDict):
    id: ReadOnly[int]
    name: str


class Strict(TypedDict, closed=True):
    host: str
    port: NotRequired[int]


class Opts(TypedDict, total=False):
    verbose: bool
    level: Required[int]


def make_point(x: int, y: int) -> Point:
    return {'x': x, 'y': y}


def rename(f: Frozen, new_name: str) -> None:
    f['id'] = 0  # expect-error
    f['name'] = new_name


def strict_port(s: Strict) -> int:
    return s.get('port', 80)


def bad_strict() -> Strict:
    return {'host': 'a', 'port': 1, 'extra': 2}  # expect-error


def configure(**kwargs: Unpack[Opts]) -> str:
    return str(kwargs['level']) + ':' + str(kwargs.get('verbose', False))


def try_configure() -> str:
    try:
        return configure(verbose=True)  # expect-error
    except KeyError:
        return 'missing level'


p = make_point(1, 2)
reveal_type(p.get('label'))
reveal_type(p | {'label': 'pt'})
assert p['x'] == 1
frozen: Frozen = {'id': 7, 'name': 'a'}
rename(frozen, 'b')
assert frozen['name'] == 'b'
assert strict_port({'host': 'h'}) == 80
assert configure(level=3) == '3:False'
assert configure(level=2, verbose=True) == '2:True'
assert try_configure() == 'missing level'
assert bad_strict()['extra'] == 2
